const scannerPath = process.argv[2] || '../scanner/20260317/index.html';

function calculateSMA(data, period) {
  const sma = [];
  for (let i = 0; i < data.length; i++) {
    if (i < period - 1) {
      sma.push(null);
      continue;
    }
    let sum = 0;
    for (let j = 0; j < period; j++) {
      sum += data[i - j][2]; // use Close price
    }
    sma.push(sum / period);
  }
  return sma;
}

